    "agents/q_agent.py": "\"\"\"Tabular Q-Learning agent implementation for Tic-Tac-Toe.\"\"\"\nfrom __future__ import annotations\nimport copy\nimport random\nfrom typing import Dict, List, Optional, Tuple\nimport numpy as np\nDEFAULT_LEARNING_RATE: float = 0.1\nDEFAULT_DISCOUNT_FACTOR: float = 0.95\nDEFAULT_EPSILON: float = 0.1\n\nclass QLearningAgent:\n    \"\"\"\n    Implements a Tabular Q-Learning agent with epsilon-greedy exploration.\n\n    The Q-table maps hashable state representations (tuples of integers) to lists\n    of action values (one per possible move index 0-8).\n    \"\"\"\n    lr: 'float'\n    gamma: 'float'\n    epsilon: 'float'\n\n    def __init__(self, lr: float=DEFAULT_LEARNING_RATE, gamma: float=DEFAULT_DISCOUNT_FACTOR, epsilon: float=DEFAULT_EPSILON) -> None:\n        \"\"\"\n        Initialize the Q-Learning agent.\n\n        Args:\n            lr: The learning rate (alpha) for the Bellman update. Should be in (0, 1].\n            gamma: The discount factor for future rewards. Should be in [0, 1).\n            epsilon: The probability of choosing a random action during exploration.\n                     In [0, 1]. Higher values lead to more exploration.\n        \"\"\"\n        ...\n    def act(self, state: np.ndarray, valid_actions: List[int]) -> int:\n        \"\"\"\n        Select an action based on the current state using epsilon-greedy policy.\n\n        Args:\n            state: The current environment observation as a numpy array (length 9, dtype float32/int). \n                   It is converted to a tuple internally for dictionary keying.\n            valid_actions: A list of integer action indices that are legal in the current state.\n                           The selected action will always be drawn from this list.\n\n        Returns:\n            An integer from `valid_actions` representing the chosen move index.\n\n        Raises:\n            ValueError: If `valid_actions` is empty.\n\n        Behavior:\n            - With probability epsilon, returns a uniformly random action from `valid_actions`.\n            - Otherwise, returns an action from `valid_actions` that maximizes the Q-value for `state`.\n              If multiple actions have the same maximal Q-value, one is chosen arbitrarily (deterministic order).\n            - If the state has never been seen, treats all unseen actions' Q-values as 0.\n        \"\"\"\n        ...\n    def learn(self, state: np.ndarray, action: int, reward: float, next_state: np.ndarray, done: bool, valid_actions_next: List[int]) -> None:\n        \"\"\"\n        Perform a Q-Learning update step (Bellman equation).\n\n        Updates the Q-value for (state, action) using the target:\n        R + gamma * max_{a' in valid_actions_next} Q(next_s, a') if not done, else R.\n\n        Args:\n            state: The state before the action as a numpy array. Must be convertible to tuple for keying.\n            action: The integer action taken in 'state'.\n            reward: The immediate reward received after taking 'action'.\n            next_state: The resulting state after 'action' as a numpy array. Must be convertible to tuple for keying.\n            done: Boolean indicating if the episode has terminated. If True, no future\n                  reward is considered.\n            valid_actions_next: A list of integer action indices that are legal in `next_state`.\n                                Used to compute the maximum Q-value for the next state.\n        \"\"\"\n        ...\n    def q_table(self) -> Dict[Tuple[int, ...], List[float]]:\n        \"\"\"\n        Return a copy of the internal Q-table.\n\n        Returns:\n            A dictionary mapping state representations (tuples of ints) to lists of Q-values (floats).\n            The returned object is a deep copy; modifying it does not affect the agent's\n            internal state.\n        \"\"\"\n        ...",
