 6. \n    Let's trace:\n    - Reset\n    - X plays 0. Board: [1, 0, 0, 0, 0, 0, 0, 0, 0]\n    - Opponent plays 4 (center). Board: [1, 0, 0, 0, -1, 0, 0, 0, 0]\n    - X plays 3. Board: [1, 0, 0, 1, -1, 0, 0, 0, 0] (No win)\n    - Opponent plays 5. Board: [1, 0, 0, 1, -1, -1, 0, 0, 0] (No win for O)\n    - X plays 6. Board: [1, 0, 0, 1, -1, -1, 1, 0, 0]. Column 0 is 1, 1, 1. This is a vertical win for column 0, not horizontal.\n    \n    The prompt text says \"test_win_horizontal\" but the example moves (0,3,6) form a vertical line in column 0.\n    To test HORIZONTAL win (row 0), X should play indices 0, 1, 2.\n    Let's follow the name `test_win_horizontal` and ensure a horizontal win occurs, correcting the move sequence to match the intent of the test function name while keeping the logic robust.\n    \n    Correct Horizontal Sequence for X:\n    1. X plays 0\n    2. Opponent plays 4 (safe)\n    3. X plays 1\n    4. Opponent plays 5 (safe)\n    5. X plays 2 -> Win!\n    \"\"\"\n    env = TicTacToeEnv()\n    obs, _ = env.reset(seed=42)\n    obs, _, terminated, truncated, info = env.step(0)\n    assert not terminated, 'Game should not terminate yet'\n    obs, _, terminated, truncated, info = env.step(4)\n    assert not terminated, 'Game should not terminate yet'\n    obs, _, terminated, truncated, info = env.step(1)\n    assert not terminated, 'Game should not terminate yet'\n    obs, _, terminated, truncated, info = env.step(5)\n    assert not terminated, 'Game should not terminate yet'\n    obs, reward, terminated, truncated, info = env.step(2)\n    assert terminated, 'Game should be terminated on win'\n    assert reward == 1.0, f'Reward should be +1 for winner, got {reward}'\n\ndef test_draw():\n    \"\"\"Simulate a full board fill without wins. Check `terminated` is True and `reward` is 0.\"\"\"\n    env = TicTacToeEnv()\n    obs, _ = env.reset(seed=42)\n    env = TicTacToeEnv()\n    obs, _ = env.reset(seed=42)\n    obs, _, terminated, truncated, info = env.step(4)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(0)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(5)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(8)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(1)\n    assert not terminated\n    assert not terminated\n    assert not terminated\n    assert not terminated\n    assert not terminated\n    env = TicTacToeEnv()\n    obs, _ = env.reset(seed=42)\n    seq = [4, 0, 5, 8, 1, 2, 6, 3, 7]\n    for i, action in enumerate(seq):\n        obs, reward, terminated, truncated, info = env.step(action)\n        if terminated:\n            raise AssertionError(f'Game terminated prematurely on move {i + 1} with action {action}')\n        assert not terminated\n    env = TicTacToeEnv()\n    obs, _ = env.reset(seed=42)\n    obs, _, terminated, truncated, info = env.step(0)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(4)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(8)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(1)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(6)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(2)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(3)\n    assert not terminated\n    obs, _, terminated, truncated, info = env.step(5)\n    assert not terminated\n    obs, reward, terminated, truncated, info = env.step(7)\n    assert terminated, 'Game should be terminated on draw'\n    assert reward == 0.0, f'Reward should be 0 for draw, got {reward}'\n\ndef test_spaces_metadata():\n    \"\"\"Assert `observation_space.shape == (9,)` and `action_space.n == 9`.\"\"\"\n    env = TicTacToeEnv()\n    assert env.observation_space.shape == (BOARD_SIZE,), f'Observation space shape mismatch: {env.observation_space.shape}'\n    assert env.action_space.n == BOARD_SIZE, f'Action space n mismatch: {env.action_space.n}'\n",
